      RAISE EXCEPTION 'expected 171 Phase-2 prompt rows, found %', n;
    END IF;

    SELECT count(*) INTO n
    FROM public.prompt_templates
    WHERE prompt_text LIKE '%[PREPAREFORU_DYNAMIC_OUTPUT_CONTRACT]%';
    IF n <> 171 THEN
      RAISE EXCEPTION 'contract marker missing on at least % prompts', 171 - n;
    END IF;

    SELECT count(*) INTO n
    FROM public.prompt_templates
    WHERE     position('visual_engine' in prompt_text) > 0
      OR     position('render_type' in prompt_text) > 0
      OR     position('headers_en' in prompt_text) > 0
      OR     position('rows_en' in prompt_text) > 0
      OR     position('title_en' in prompt_text) > 0
      OR     position('title_te' in prompt_text) > 0
      OR     prompt_text ~ '(?m)^#[[:space:]]*PROMPT METADATA[[:space:]]*$'
      OR     position('diagram' in prompt_text) > 0;
    IF n <> 0 THEN
      RAISE EXCEPTION 'legacy application-format content still present on % stored prompts', n;
    END IF;

    SELECT count(*) INTO n
    FROM public.prompt_templates
    WHERE prompt_text ~ '(?m)^#[[:space:]]*VISUAL QUALITY RULES[[:space:]]*$';
    IF n <> 0 THEN RAISE EXCEPTION 'generic visual quality rules still present on % rows', n; END IF;

    SELECT count(*) INTO n
    FROM public.prompt_templates
    WHERE prompt_text ~ '(?m)^#[[:space:]]*(?:[✅❌]️?[[:space:]]*)?(?:GOOD|BAD) VISUAL EXAMPLE(?:S)?[[:space:]]*$';
    IF n <> 0 THEN RAISE EXCEPTION 'GOOD/BAD visual exemplar headings still present on % rows', n; END IF;

    SELECT count(*) INTO n
    FROM public.prompt_templates
    WHERE prompt_text ~ '(?m)^#[[:space:]]*SUPPORTED VISUAL TYPES[[:space:]]*$';
    IF n <> 0 THEN RAISE EXCEPTION 'supported-visual-types heading still present on % rows', n; END IF;

    SELECT count(*) INTO n
    FROM public.prompt_templates
    WHERE prompt_text ~ '(?m)^#[[:space:]]*VISUAL GENERATION REQUIREMENT[[:space:]]*$';
    IF n <> 0 THEN RAISE EXCEPTION 'generic visual generation-requirement heading still present on % rows', n; END IF;

